//www.w3.org/1998/Math/MathML",children:(0,n.jsxs)(e.semantics,{children:[(0,n.jsx)(e.mrow,{children:(0,n.jsx)(e.mn,{children:"0"})}),(0,n.jsx)(e.annotation,{encoding:"application/x-tex",children:"0"})]})})}),(0,n.jsx)(e.span,{className:"katex-html","aria-hidden":"true",children:(0,n.jsxs)(e.span,{className:"base",children:[(0,n.jsx)(e.span,{className:"strut",style:{height:"0.6444em"}}),(0,n.jsx)(e.span,{className:"mord",children:"0"})]})})]}),". Uma amostra \xe9 mantida se todas as verifica\xe7\xf5es passarem."]}),"\n",(0,n.jsxs)(e.p,{children:["Os circuitos verificados medem os auxiliares no registrador ",(0,n.jsx)(e.code,{children:"checks_c"}),", ent\xe3o uma amostra \xe9 mantida se todos os bits desse registrador forem ",(0,n.jsx)(e.code,{children:"0"}),". Em geral, o m\xe9todo ",(0,n.jsx)(e.code,{children:"get_postselection_method"})," das inst\xe2ncias de ",(0,n.jsx)(e.code,{children:"CheckedCircuit"})," retornadas por ",(0,n.jsx)(e.code,{children:"add_pauli_checks"})," mapeia a bitstring de um shot para a s\xedndrome de todas as verifica\xe7\xf5es de uma vez; para verifica\xe7\xf5es encontradas para os estabilizadores do estado preparado, cada s\xedndrome \xe9 apenas o bit do seu auxiliar, ent\xe3o lemos o registrador diretamente."]}),"\n",(0,n.jsx)(e.p,{children:"No gr\xe1fico, vemos que adicionar mais verifica\xe7\xf5es faz a taxa de p\xf3s-sele\xe7\xe3o cair. Embora o objetivo da detec\xe7\xe3o de erros seja capturar o maior n\xfamero poss\xedvel de erros, \xe0 medida que a taxa de p\xf3s-sele\xe7\xe3o cai, mais shots podem ser necess\xe1rios para atingir uma determinada precis\xe3o-alvo. Se a taxa de p\xf3s-sele\xe7\xe3o cair demais, o n\xfamero de shots necess\xe1rio para coletar uma amostra l\xf3gica pode se tornar proibitivo. Neste exemplo, a taxa de p\xf3s-sele\xe7\xe3o parece convergir, o que implica que as verifica\xe7\xf5es adicionais contribuem com cada vez menos capacidade de detec\xe7\xe3o. Embora adicionar mais verifica\xe7\xf5es de Pauli geralmente proporcione maior capacidade de detec\xe7\xe3o de erros, isso vem ao custo de maior profundidade do circuito e de maior custo de amostragem."}),"\n",(0,n.jsx)(e.pre,{children:(0,n.jsx)(e.code,{className:"language-python",children:'def keep_mask(out):\n    """Per-shot True/False: every ancilla read 0, so every Pauli check passed."""\n    if "checks_c" not in out:  # the bare payload has no checks\n        return np.ones(out["meas"].shape[:-1], dtype=bool)\n    return ~out["checks_c"].any(axis=-1)\n\n# masks[k][i]: kept shots of stabilizer i measured on the variant with k checks\nmasks = [keep_mask(out) for out in outs]\npsrs_arr = np.array([mask.mean(axis=-1) for mask in masks]).T\nks = np.arange(psrs_arr.shape[1])\n\nfig, ax = plt.subplots(figsize=(8, 4))\nax.plot(ks, psrs_arr.T, color="darkorange", alpha=0.15, linewidth=1)\nax.plot(\n    ks,\n    np.median(psrs_arr, axis=0),\n    color="black",\n    linewidth=1,\n    linestyle="--",\n    label="median",\n)\nax.set(\n    xlabel="Checks committed",\n    ylabel="Post-selection rate",\n    ylim=(0, 1.05),\n    title=f"Per-stabilizer post-selection rate ({len(psrs_arr)} stabilizers)",\n)\nax.legend()\nax.grid(True, alpha=0.3)\nplt.tight_layout()\nplt.show()\n'})}),"\n",(0,n.jsx)(e.p,{children:(0,n.jsx)(e.img,{alt:"Output of the previous code cell",src:a(49127).A+"",width:"790",height:"390"})}),"\n",(0,n.jsx)(e.h3,{id:"10-compare-fidelities-of-original-and-postselected-noisy-states",children:"10. Compare as fidelidades dos estados ruidosos original e p\xf3s-selecionado"}),"\n",(0,n.jsx)(e.p,{children:"Vemos que p\xf3s-selecionar apenas as amostras sem erros detectados melhora bastante o valor esperado de cada estabilizador e, portanto, melhora a fidelidade estimada do estado estabilizador. Embora os valores p\xf3s-selecionados tenham sido calculados usando apenas as amostras que passaram em todas as verifica\xe7\xf5es, os valores esperados s\xe3o muito mais precisos e a vari\xe2ncia amostrada \xe9 menor. Tamb\xe9m podemos ver agora que a taxa de p\xf3s-sele\xe7\xe3o acima estava, na verdade, convergindo para um valor semelhante \xe0 fidelidade do circuito ruidoso. A taxa de p\xf3s-sele\xe7\xe3o estava convergindo porque as verifica\xe7\xf5es estavam capturando a grande maioria dos erros que realmente ocorriam durante a execu\xe7\xe3o do circuito."}),"\n",(0,n.jsx)(e.pre,{children:(0,n.jsx)(e.code,{className:"language-python",children:'def expectation_values(out, mask):\n    """EV of each stabilizer from the shots of ``out`` kept by ``mask``.\n\n    Bit q of ``meas`` is virtual qubit q, so a stabilizer\'s eigenvalue in a shot is the parity of\n    the bits in its support, times its sign.\n    """\n    support = stabilizers.x | stabilizers.z\n    parity = (out["meas"] & support[:, None, :]).sum(axis=-1) % 2\n    signs = np.where(stabilizers.phase == 2, -1.0, 1.0)\n    eigenvalues = np.where(parity, -1.0, 1.0) * signs[:, None]\n    kept = mask.sum(axis=-1)\n    return np.where(\n        kept > 0,\n        (eigenvalues * mask).sum(axis=-1) / np.maximum(kept, 1),\n        np.nan,\n    )\n\nevs_noisy = expectation_values(outs[0], masks[0])\nevs_post = expectation_values(outs[-1], masks[-1])\nprint(\n    f"ideal fidelity: 1.0\\n"\n    f"noisy fidelity: {np.nanmean(evs_noisy):.4f}\\n"\n    f"postselected fidelity: {np.nanmean(evs_post):.4f}\\n"\n    f"mean post-sel rate: {masks[-1].mean():.3f}\\n"\n)\n\nevs_ideal = np.ones(len(stabilizers))\nidx = np.arange(len(stabilizers))\n\ndef cum_mean_sem(ys):\n    valid = ~np.isnan(ys)\n    s = np.cumsum(np.where(valid, ys, 0.0))\n    s2 = np.cumsum(np.where(valid, ys**2, 0.0))\n    n = np.maximum(np.cumsum(valid).astype(float), 1)\n    mean = s / n\n    sem = np.sqrt(np.maximum(s2 / n - mean**2, 0) / n)\n    return np.where(np.cumsum(valid) > 0, mean, np.nan), sem\n\ndef strip(ax, ys, color, label):\n    m, s = np.nanmean(ys), np.nanstd(ys)\n    ax.axhspan(\n        m - s, m + s, color=color, alpha=0.15, label=f"{label} mean \xb1 std"\n    )\n    ax.axhline(m, color=color, linewidth=1, linestyle="--")\n\nfig, ax = plt.subplots(figsize=(8, 4))\nax.axhline(np.nanmean(evs_ideal), color="black", linewidth=1.5, label="ideal")\nstrip(ax, evs_noisy, "red", "noisy")\nstrip(ax, evs_post, "green", "post-sel")\nax.scatter(\n    idx, evs_noisy, color="red", s=22, alpha=0.7, zorder=3, label="noisy <G>"\n)\nax.scatter(\n    idx,\n    evs_post,\n    color="green",\n    s=22,\n    alpha=0.7,\n    zorder=3,\n    label="post-sel <G>",\n)\nax.set(\n    xlabel="stabilizer index",\n    ylabel=r"$\\langle G \\rangle$",\n    ylim=(-0.1, 1.1),\n    title="Per-stabilizer EVs",\n)\nax.legend(loc="lower left", ncol=2)\nax.grid(True, alpha=0.3)\nplt.tight_layout()\nplt.show()\n\nM = np.arange(1, len(stabilizers) + 1)\nfig, ax = plt.subplots(figsize=(8, 4))\nfor ys, color, label in [\n    (evs_ideal, "black", "ideal"),\n    (evs_noisy, "red", "noisy"),\n    (evs_post, "green", "post-sel"),\n]:\n    cm, sem = cum_mean_sem(ys)\n    ax.plot(M, cm, color=color, linewidth=1.5, label=label)\n    ax.fill_between(M, cm - sem, cm + sem, color=color, alpha=0.15)\nax.set(\n    xlabel="number of stabilizers averaged",\n    ylabel="running fidelity estimate",\n    title="Fidelity convergence vs. number of stabilizers",\n)\nax.legend()\nax.grid(True, alpha=0.3)\nplt.tight_layout()\nplt.show()\n'})}),"\n",(0,n.jsx)(e.pre,{children:(0,n.jsx)(e.code,{className:"language-text",children:"ideal fidelity: 1.0\nnoisy fidelity: 0.5582\npostselected fidelity: 0.9747\nmean post-sel rate: 0.535\n"})}),"\n",(0,n.jsx)(e.p,{children:(0,n.jsx)(e.img,{alt:"Output of the previous code cell",src:a(4215).A+"",width:"790",height:"390"})}),"\n",(0,n.jsx)(e.p,{children:(0,n.jsx)(e.img,{alt:"Output of the previous code cell",src:a(77262).A+"",width:"790",height:"390"})}),"\n",(0,n.jsx)(e.p,{children:"Como um \xfanico conjunto de verifica\xe7\xf5es serve para todos os estabilizadores, h\xe1 uma \xfanica curva de gamma para observar: o valor da fun\xe7\xe3o de custo ap\xf3s cada verifica\xe7\xe3o ser confirmada. Para outros problemas, em um conjunto diferente de qubits f\xedsicos e com um modelo de ru\xeddo imperfeito (lembre-se de que o modelo de ru\xeddo deste tutorial modelou exatamente o ru\xeddo que afeta as amostras), a ordem em que as verifica\xe7\xf5es s\xe3o adicionadas aos qubits alvo pode ter um efeito mais pronunciado sobre como a curva converge."}),"\n",(0,n.jsxs)(e.p,{children:["Essa curva de gamma convergindo para ",(0,n.jsx)(e.code,{children:"1.0"})," implica que verifica\xe7\xf5es adicionais n\xe3o conseguir\xe3o detectar muito mais erro, pois h\xe1 muito pouco erro modelado que n\xe3o seja coberto pelas verifica\xe7\xf5es. Isso refor\xe7a nossa observa\xe7\xe3o anterior de que a converg\xeancia da taxa de p\xf3s-sele\xe7\xe3o se deve \xe0 falta de erro descoberto no circuito."]}),"\n",(0,n.jsx)(e.pre,{children:(0,n.jsx)(e.code,{className:"language-python",children:'costs = [variant.cost for variant in checked]\n\nfig, ax = plt.subplots(figsize=(8, 4))\nax.plot(range(len(costs)), costs, color="steelblue", marker="o")\nax.set(\n    xlabel="Checks committed",\n    ylabel="Gamma",\n    yscale="log",\n    title="Gamma of the noise left uncovered by the checks",\n)\nax.grid(True, alpha=0.3, which="both")\nplt.tight_layout()\nplt.show()\n'})}),"\n",(0,n.jsx)(e.p,{children:(0,n.jsx)(e.img,{alt:"Output of the previous code cell",src:a(72535).A+"",width:"790",height:"390"})}),"\n"]})}function d(s={}){const{wrapper:e}={...(0,l.R)(),...s.components};return e?(0,n.jsx)(e,{...s,children:(0,n.jsx)(o,{...s})}):o(s)}},11083(s,e,a){a.d(e,{A:()=>i});const i=a.p+"assets/images/11a6cb5d-8a64-42ab-8007-16f7f1ba4e82-0-809e5edda7b9d18bb03a24e77f898cf7.avif"},83932(s,e,a){a.d(e,{A:()=>i});const i=a.p+"assets/images/3b01c2ab-7688-48fe-837b-63885dd42db6-0-cc0224d39057444835dcdab6b41629cb.avif"},55124(s,e,a){a.d(e,{A:()=>i});const i=a.p+"assets/images/467a0a2b-1-089f47fd14721dff7a0798a269a4cafc.avif"},74389(s,e,a){a.d(e,{A:()=>i});const i=a.